(function(){
const sections=['topics','units','resources','events','gallery','partners','news'];
const textKeys=['id','title','description','date','url','category','image','course','year','logo','email','phone','address','page','source','body'];
function safeLink(v){if(typeof v!=='string'||!v)return '';try{const u=new URL(v);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}}
function safeImage(v){if(typeof v!=='string')return '';if(/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(v))return v;return safeLink(v)||(/^assets\/[a-zA-Z0-9_./-]+$/.test(v)&&!v.includes('..')?v:'')}
function validate(d){if(!d||d.schemaVersion!==1||!d.settings||!d.pages)throw Error('El archivo no tiene el formato de contenido de este sitio.');const out={schemaVersion:1,settings:{},pages:{}};for(const k of ['siteName','school','specialty','tagline','intro','instagram','email','portal']){if(typeof d.settings[k]!=='string')throw Error('Falta la configuración: '+k);out.settings[k]=d.settings[k]}for(const [k,p]of Object.entries(d.pages)){if(!/^[a-z]+$/.test(k)||typeof p.title!=='string'||typeof p.description!=='string')throw Error('Página inválida');out.pages[k]={title:p.title,description:p.description}}if(!out.pages.noticias)out.pages.noticias={"title":"Noticias y actualidad","description":"Novedades sobre hormigón, estructuras, normativa e innovación para conectar el aula con la práctica profesional."};for(const k of sections){if(k==='news'&&d[k]===undefined){out[k]=[];continue}if(!Array.isArray(d[k]))throw Error('Falta la colección '+k);out[k]=d[k].map(x=>{if(!x||typeof x!=='object'||typeof x.id!=='string'||typeof x.title!=='string')throw Error('Registro inválido en '+k);const a={};for(const key of textKeys){if(x[key]!==undefined){if(typeof x[key]!=='string')throw Error('Campo inválido: '+key);a[key]=x[key]}}if(x.example)a.example=true;return a})}return out}
function db(){return new Promise((resolve,reject)=>{const r=indexedDB.open('hormigon-armado-editor',1);r.onupgradeneeded=()=>r.result.createObjectStore('draft');r.onerror=()=>reject(r.error);r.onsuccess=()=>resolve(r.result)})}
async function get(){const d=await db();return new Promise((resolve,reject)=>{const t=d.transaction('draft');const r=t.objectStore('draft').get('content');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);t.oncomplete=()=>d.close()})}
async function save(v){const d=await db();return new Promise((resolve,reject)=>{const t=d.transaction('draft','readwrite');t.objectStore('draft').put(validate(v),'content');t.oncomplete=()=>{d.close();resolve()};t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error)})}
async function seed(){const r=await fetch('data/content.json',{cache:'no-cache'});if(!r.ok)throw Error('No se pudo cargar el contenido del sitio.');return validate(await r.json())}
window.ContentStore={safeLink,safeImage,validate,get,save,seed};
})();
